package com.lbos.commercecustomer.controller; import com.lbos.commercecustomer.dto.request.*;import com.lbos.commercecustomer.dto.response.*;import com.lbos.commercecustomer.service.*;import io.swagger.v3.oas.annotations.security.SecurityRequirements;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import java.time.OffsetDateTime;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/product-categories") public class CategoryController {private final CategoryService service;public CategoryController(CategoryService s){service=s;}private <T> ApiResponse<T> ok(HttpServletRequest r,String m,T d){return ApiResponse.of(Optional.ofNullable(r.getHeader("X-Correlation-Id")).orElse("not-provided"),m,d);}@PostMapping public ResponseEntity<ApiResponse<CategoryResponse>> create(@Valid @RequestBody CategoryRequest r,HttpServletRequest h){return ResponseEntity.status(201).body(ok(h,"Category created",service.create(r)));}@SecurityRequirements @GetMapping("/{id}") public ApiResponse<CategoryResponse> get(@PathVariable Long id,HttpServletRequest h){return ok(h,"Category retrieved",service.get(id));}@SecurityRequirements @GetMapping public ApiResponse<PageResponse<CategoryResponse>> search(@RequestParam(defaultValue="") String q,@RequestParam(defaultValue="ACTIVE") String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size,HttpServletRequest h){return ok(h,"Categories retrieved",service.search(q,status,page,size));}@SecurityRequirements @GetMapping("/active") public ApiResponse<List<CategoryResponse>> active(HttpServletRequest h){return ok(h,"Active categories retrieved",service.active());}@PatchMapping("/{id}") public ApiResponse<CategoryResponse> update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r,HttpServletRequest h){return ok(h,"Category updated",service.update(id,r));}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);}}